      if (!state.roundEnded) telemetry?.begin(playtestSnapshot());
      setFeedback(resumedOldFurnace ? "旧炉药力已保留。可立即收丹，继续炼化按当前炉险结算。" : "已回到上次停炉的位置。", "good");
