    if(!state.pill.craftKind&&hasTool('pattern_tray')&&(state.pill.scars||0)>0&&!state.pill.patternTrayUsed){state.pill.patternTrayUsed=true;campaign.economy.nextRiskBuffer=1;triggerLog('回纹托 · 下炉首炼免炸炉','good');}
