  if(!j.width||!c.height){backing.hidden=true;return;}
  const leftPad=Math.max(0,Math.min(12,j.left-v.left-3)),rightPad=Math.max(0,Math.min(12,v.right-j.right-3));
  const bottomEdge=Math.max(j.bottom,c.bottom);
